"""Bounded prose editing; preserve ordered numerical evidence and technical blocks."""
from pathlib import Path
import re,json,hashlib
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'e-book/manuscript/editorial_v12';OUT.mkdir(parents=True,exist_ok=True)
base=(ROOT/'e-book/exports/v11/ebook_review_v11.md').read_text(encoding='utf-8');text=base;changes=[]
pattern=r'[+−-]?\d+(?:,\d{3})*(?:\.\d+)?(?:[eE][+−-]?\d+)?'
def edit(ch,prefix,new,why):
 global text
 start=text.index(f'# {ch}장 ');end=text.find('\n# ',start+1);end=len(text) if end<0 else end
 section=text[start:end];matches=[p for p in section.split('\n\n') if p.lstrip('\n').startswith(prefix)];assert len(matches)==1,(ch,prefix,len(matches))
 old=matches[0];assert old!=new
 assert re.findall(pattern,old)==re.findall(pattern,new),(ch,prefix,re.findall(pattern,old),re.findall(pattern,new))
 text=text[:start]+section.replace(old,new,1)+text[end:];changes.append({'chapter':ch,'reason':why,'before':old,'after':new})
edit(5,'JH Motors의 CRM 담당자가','JH Motors의 CRM 담당자는 차량 가치 안내 A와 시승 편의 안내 B 중 어느 정책이 실제 시승 완료를 늘리는지 알고 싶다. H는 해당 실험 메시지를 보내지 않는 비교 정책이다. 이 두 장에서는 같은 합성 사례로 결과를 읽고 다음 실험을 설계한다. 고객 수와 행동 확률은 교육용 가정이다. 실제 자동차 회사의 성과나 자료 규모에 따른 현실성의 검증으로 읽지 않는다.','질문을 먼저 제시하고 합성 자료의 범위를 한곳에 모음')
edit(5,'여기까지는 이번 표본을','이번 표본에서는 +0.93pp의 차이를 얻었다. 다른 고객을 배정했다면 완료 고객 수와 추정값도 달라졌을 것이다. 고객별 결과와 무작위배정의 표본 변동이 있기 때문이다. 이 추정값을 다른 고객에게 옮겨 판단하려면 얼마나 큰 흔들림이 남아 있는지 함께 읽어야 한다.','점추정에서 불확실성으로 넘어가는 연결을 직접 서술')
edit(5,'교육용 독립 이항 가정으로','교육용 독립 이항 가정에서 위 식으로 계산한 표준오차는 약 0.28pp다. 효과가 0.28pp라거나 고객의 0.28%가 오류라는 뜻이 아니라, +0.93pp라는 추정값의 정밀도를 읽는 눈금이다. 같은 비율에서 독립 고객의 정보가 늘면 보통 표준오차는 작아진다. 같은 고객의 클릭 기록을 복제하는 일은 독립 정보를 늘리지 않으므로 로그 행 수를 고객 수 대신 넣어서는 안 된다.','같은 주의 문장을 합치고 분모 선택에 연결')
edit(5,'신뢰구간은 이런 흔들림을','신뢰구간은 효과의 불확실성을 범위로 나타낸다. 단순 정규 근사에서는 차이의 양쪽에 임계값과 표준오차를 곱한 폭을 붙인다고 이해할 수 있다. 이 설명은 구간 폭의 직관을 위한 것이다. 실제 보고에는 각 군의 Wilson 경계를 결합한 Newcombe 차이 구간과 검증 장부의 값을 사용한다. 숫자가 비슷하더라도 두 절차를 같은 방법으로 부르지 않는다.','교육용 근사와 실제 보고 절차의 차이를 보존하며 중복 축소')
edit(5,'왜 이 책은 미보정 p만','이 사례에서는 B-A뿐 아니라 A-H와 B-H도 묻기 때문에 미보정 p만으로 판단하지 않는다. 세 완료 대비를 주분석 가족으로 정하고 Bonferroni를 적용했다. 가족 유의수준 5%를 나누면 각 대비의 기준은 0.05/3이고, 대응 양측 구간 수준은 약 98.33%다. B-A의 보정 p는 약 0.00274다. 보정 p는 가족 기준과, 미보정 p는 나눈 기준과 비교한다. 보정 p에 기준까지 다시 나누면 중복 보정이다.','반복 질문형 도입을 줄이고 비교 규칙을 명확히 함')
edit(5,'그렇다면 지금 통계적으로','정한 완료 가족과 분석 가정 아래에서는 B가 A보다 완료율을 높인다는 근거가 있다. 이 결론은 시승 완료에 관한 것이지 계약 이익에 관한 것이 아니다. H 역시 이번 실험 메시지의 미발송일 뿐 모든 CRM 접촉을 막은 전사 대조군은 아니다. B-A는 문구 정책의 차이, B-H는 이번 메시지를 보내는 정책과 보내지 않는 정책의 차이를 뜻한다. 보고서에도 대비 이름을 남겨 같은 계산이 다른 사업 주장의 근거로 쓰이지 않게 한다.','통계 결과를 보고서의 대비 문장으로 연결')
edit(5,'회의에 남길 문장은 결국','회의에는 완료율에서 B가 높았고 정한 완료 가족에서 개선 근거가 있다는 문장을 남긴다. 사업 최소 효과의 확정 충족은 별도 판단이며 관계 안전은 통과했다고 말할 수 없다. 실제 수익과 확대 운영에는 추가 자료가 필요하다. 보고서를 쓸 때는 분모와 효과, 불확실성 및 가정을 먼저 적고 통계 판단, 사업 판단, 보호 판단을 나눈다. 앞의 긍정적인 결과로 뒤의 미확인 조건까지 채우지 않는다.','장의 요약을 실제 보고 순서로 바꿈')
edit(6,'같은 담당자가 다음 실험의','다음 실험을 설계할 때는 보유 고객 수보다 먼저 판단할 지표와 변화 크기, 감수할 오류 수준을 정한다. 앞 장에서 정한 분모와 효과를 원하는 정밀도와 발견 능력으로 평가하려면 어떤 정보가 필요한지 묻는 것이다. 시승 완료, 드문 계약, 관계 악화는 필요한 수와 시간이 다르다. CRM에 고객이 많다는 사실만으로 어느 질문에도 충분하다고 답할 수는 없다.','앞 장의 해석과 후속 설계의 역할을 분리')
edit(6,'다음 표는 기존 원문을','다음 표는 독립 개인의 이항 결과, 동일한 두 군 배정, 단일 양측 비교, 유의수준 5%, 검정력 80%를 가정한 계획이다. 손실과 군집, 중간 분석 보정은 포함하지 않았다. 희귀 불만과 작은 시승 변화에는 장부의 수치 검정력 탐색값을 사용했다. 근사식과 끝자리가 다를 수 있으며, 각 수치는 이 조건에서 필요한 고객 수이지 모든 실험의 최소 인원이 아니다.','원문 보존에 대한 제작 설명을 독자가 쓸 조건 설명으로 교체')
edit(6,'이제 같은 사례의 실제 배정','같은 사례의 A는 차량 가치 안내, B는 시승 편의 안내, H는 해당 실험 메시지 미발송이다. 앞 장에서 사용한 분모와 결과는 다음과 같다. 모집단 속성, 배정, 전달, 결과, 시점에는 고정된 별도 난수 스트림을 사용했고 유의한 결과가 나올 때까지 다시 뽑지 않았다. 명세는 생성 전에 로컬에서 동결했다. 외부 기관의 사전등록이나 실제 기업 현장 실험이 아니라 이 설계로 생성한 합성 결과다.','배정표 앞의 반복 메타 설명을 출처 설명으로 통합')
edit(6,'계약의 계획 검정력이 낮다는','계약의 계획 검정력이 낮아도 사건 수와 구간을 분석해 탐색 근거로 남길 수 있다. 다만 계획한 크기의 개선이 있더라도 놓칠 가능성이 큰 설계였음을 함께 설명해야 한다. 이미 얻은 관측 효과를 다시 검정력 계산에 넣으면 p와 비슷한 정보를 반복하기 쉽다. 현재 결과에는 효과와 신뢰구간을 보고하고, 후속 설계에는 사업적으로 중요한 효과를 명시한다.','분석 금지와 근거 제한의 구분을 유지하고 행동으로 마무리')
edit(6,'따라서 회의에서는 등록 종료일과','등록 종료일과 최종 결과 확정일을 따로 적는다. 늦게 들어온 고객을 미완료로 확정하면 아직 기다릴 시간을 실패로 바꾸고, 관측이 빨리 끝난 고객만 고르면 모집 시점의 구성이 달라질 수 있다. 고정 개인별 창을 사용한다면 성숙한 결과를 읽고 중간 보고에는 배정 수, 관측 성숙 수, 현재 사건 수를 나눈다. 시간 정보를 다루는 다른 분석을 설계할 수는 있지만 조기 스냅샷을 완성 자료처럼 쓰지는 않는다.','기간 설명을 설계서와 중간 보고에 남길 항목으로 연결')
edit(6,'표본만의 영향을 보려면','작은 기본 자료와 큰 자료는 정책과 생성 모형도 다르므로 유의성의 차이를 고객 수만으로 설명할 수 없다. 표본만의 영향을 분리한 다음 모의실험에서는 A=9%, B=10%의 독립 이항 모형을 고정하고 군당 수를 바꾸어 5,000회씩 반복했다. 대비의 양측 기준은 0.05/3이다. 표는 같은 교육 가정에서 절차의 발견 능력을 비교한 결과이며 새 기업 성과가 아니다.','장부와 원문을 반복 소개하는 문구 제거')
edit(6,'담당자가 최종 설계서에 적을','최종 설계서에는 적용 모집단과 적격 조건, 배정 단위와 정책, 주지표 분모와 개인별 창을 연결한다. 기준율과 계획 효과, 유의수준과 검정력, 비교 가족과 종료 규칙을 적고 사업 기준, 보호 조건, 누락과 관측 지연 처리도 함께 정한다. 그래야 어느 효과를 언제 어떤 절차로 판단할 정보가 충분한지 답할 수 있다. 총 고객 수는 이 질문들을 정한 뒤에 나오는 계획값이다.','설계의 입력과 결과 순서를 분명히 함')
edit(12,'이 장을 덮을 때 남길 것은','이 장에서는 가상 자동차 회사 JH Motors의 시승 안내를 맡아 한 장의 결정문을 완성한다. 누구에게 무엇을 바꾸려 했고, 어떤 근거로 어디까지 적용하며, 무엇이 들어오면 다시 판단할지 쓴다. 회사와 고객, 사건과 비용은 교육용 합성 자료다. 실제 회의나 승인 기록을 재현한 이야기가 아니라 기존 설계와 결과를 연결하고 미확정 조건을 처리하는 연습이다. 마지막 결정문은 이 자료로 작성할 수 있는 예시다.','장 목표와 합성 및 승인 경계를 한 문단으로 정리')
edit(12,'문제를 고르는 출발점은','잠재 고객이 차량에 관심을 보인 뒤 실제 시승을 완료하도록 돕는 안내를 비교한다. 기존 차량 가치 안내보다 예약 편의를 강조하면 행동 장벽이 낮아질 수 있다는 가설이다. 자료에는 이를 뒷받침할 인터뷰나 현장 병목 조사 결과가 없다. 따라서 예약 불편이 이탈 원인으로 확인됐다고 쓰지 않는다. 동의한 고객에게 보낼 선택적 안내를 비교 가능한 정책으로 정의하고, 다음 행동인 완료에서 그 가설을 평가한다.','가설 선택의 이유와 확인하지 않은 진단을 간결히 구분')
edit(12,'다음 표는 독자가 설계 메모에','설계 메모에는 다음 명세를 남긴다. 결과를 본 뒤 고르는 요약이 아니라 앞으로 읽을 수치의 비교 조건이다. 실제 업무에서는 회사가 승인한 정의를 쓰고 변경한 부분의 버전과 시점을 기록한다.','표의 사용 목적을 짧게 제시')
edit(12,'아래 SQL은 그 실제 뷰의','아래 SQL은 실제 뷰의 필드로 작성한 읽기용 집계다. 기존 DB를 읽기 전용으로 열어 배정과 완료, 철회, 계약 합계를 다음 표와 대조했다. 이는 통계 분석 전체의 재실행은 아니다. 독자는 저장소 루트의 DB를 SQLite 클라이언트로 열어 실행할 수 있다. 다른 버전에서는 이름이 같은 뷰라도 정의부터 확인한다.','집계 검사의 범위와 실행 순서를 직접 설명')
edit(12,'여기서 TRI-V의 첫 축인','정화, Variable Control을 거친 뒤에는 전달 성공자만의 비교와 미성숙 스냅샷을 주결론에서 제외한다. 기록 경로에 문제가 있으면 그 지표의 판단을 멈춘다. 이번에는 뷰 합계를 원본 사건과 연결할 수 있으므로 정한 합성 비교를 읽을 수 있다. 실제 운영의 무작위화와 원장 정확성까지 확인한 것은 아니다. 이 경계가 있어야 B의 완료 수가 가장 크다는 관찰을 곧바로 적용 승인으로 바꾸지 않는다.','반복적인 축 소개를 실제 판단 변경으로 정리')
edit(12,'동의 철회는 발송 정책의','동의 철회는 발송 정책의 보호 지표다. 민원과 장기 이탈은 생성하지 않았으므로 철회만으로 모든 관계 손상을 설명하지 않는다. B-A 결과를 발송-H의 위험 판단으로 옮길 수도 없다. H에도 철회가 있고 실제 운영에서는 다른 접촉이 영향을 줄 수 있기 때문이다. 후속 계획에는 신규 적용에 필요한 보호 비교와 허용 한계를 명시한다. 법적 권리 침해나 중대한 피해는 통계적 유의성을 기다리지 않는 운영 중단 사유로 두며, 이는 사후 0.2pp 예시와 별개다.','미관측 보호 결과와 의무를 보존하며 반복 면책 축소')
edit(12,'두 번째 축인 해체와 입체화,','해체와 입체화, Vector Segmentation에서는 적용 대상을 확인한다. 이번 모집단은 잠재 고객이며 군별 정책 효과는 균일한 가정으로 생성했다. 지역과 차종 라벨만으로 특정 고객군의 승자를 선언하거나, 별도 집단 실습의 효과 반전을 이 실험의 발견으로 가져올 수 없다. 현재 답은 적격 잠재 고객 구성의 전체 효과다. 다른 대상을 고르려면 배정 전 고객 상태와 집단별 효과 차이, 정보량과 다중성을 계획해야 한다. 따라서 모든 CRM 고객에게 B를 보내는 확대는 현재 근거 밖이다.','축의 반복 소개를 적용 범위의 결론으로 연결')
edit(12,'입체화는 지금 자료를 끝없이','지금 자료에서 가장 큰 차이를 찾으려고 끝없이 나눌 필요는 없다. 구매 확률이 높은 고객과 연락의 증분 효과가 큰 고객은 다르다. 유입 경로나 관심 모델에서 좋아 보이는 차이를 발견하면 탐색으로 남기고 별도 표본에서 확인할 후보로 둔다. 클릭자만의 결과는 처치 뒤 행동으로 고른 비교이므로 적용 대상을 사전에 정의한 근거로 쓰지 않는다. 이번 결정문에는 확인하지 않은 집단별 이득 대신 실험 대상과 다음 적용 대상의 구성 차이를 확인할 책임을 남긴다.','불필요한 분석을 하지 않는 이유를 사례의 결정문에 연결')
edit(12,'여기까지의 결론은 전면 적용','현재는 전면 적용을 보류하고 B를 후속 검토 후보로 남긴다. 다시 판단하려면 사업 담당자가 실제 도입 기준과 변경 비용을, 고객 보호 담당자가 동의 처리와 허용 위험 및 평가 방법을, 재무 담당자가 기여액과 비용 범위를, 운영 담당자가 수용 가능한 발송 범위와 복구 경로를 확정해야 한다. 임의의 예산과 인원, 날짜로 빈칸을 채우지는 않는다. 이 조건을 승인한 뒤 되돌릴 수 있는 제한 범위를 계획할 수 있지만, 그 범위의 안전과 수익까지 현재 자료로 검증됐다고 쓰지 않는다.','보류의 의미를 역할별 미확정 조건으로 구체화')
edit(12,'제한 적용 후의 관찰과 새','추가 확인은 선택을 바꿀 질문으로 남긴다. 실제 도입 기준을 지지하는 근거와 보호 평가, 운영 가능 범위가 갖춰지면 제한 적용이나 새 실험의 승인을 요청한다. 보호에 필요한 설계와 정보량이 부족하면 확대를 열지 않고 그 확인을 우선한다. 단순 모니터링은 장애와 피해를 찾는 데 쓰되 증분 효과의 실험을 대신하지 않는다. 새 실험에는 비교 정책과 배정, 결과 창, 표본과 분석, 보호 조건을 다시 고정한다. 안전상 운영 중지와 성과상 조기 종료를 나누며 원래 실험을 유의해질 때까지 연장하지 않는다.','확인 항목을 조건별 다음 선택에 연결하고 모니터링과 실험 구분 유지')
edit(12,'독자는 이제 한 장을 쓰기','결정문을 쓰기 전에 다음 세 판단을 해 보자. 계산값을 바꾸는 문제가 아니라 각 근거로 어느 주장까지 할 수 있는지 확인하는 문제다.','과제 도입의 메타 표현 축소')
edit(12,'마지막으로 다음은 빈칸 양식이','다음은 지금까지의 해석을 연결한 결정문이다. 자신의 사례에서는 대상과 근거, 책임과 재검토 조건을 실제 값으로 바꿔 쓴다. 이 예시도 승인되지 않은 제한 적용을 실행한 것으로 기록하지 않는다.','결정문 예시 앞의 중복 설명 축소')
edit(12,'이 결정문을 자신의 업무로','결정문을 쓴 뒤 같은 내용을 다른 양식에 다시 입력할 필요는 없다. 공통 운용 기준의 여섯 항목에 지금 결정할 것, 근거와 제한, 적용 대상, 현재 선택, 추가 확인 또는 생략, 다시 검토할 조건의 위치를 연결한다. 별도 TRI-V 결정 기록에는 실험 전 기준과 결과 후 해석, 기준 변경과 재검토 이력을 같은 실험 식별자 아래 남긴다. 이 사례의 최소 사업 효과와 철회 한계는 사후 교육 가정이므로 변경 시점과 결과 열람 여부를 적는다. 담당자와 기한, 손실 한계가 미정이면 임의의 이름이나 숫자 대신 그 공란을 확정할 역할을 남긴다.','예전 상세 기록과 새 여섯 항목의 관계를 정리하고 재입력 방지')
edit(12,'기존 캠페인의 상세 계산을','1장의 기준으로 정리한 지금 선택은 주어진 대상에서 A를 B로 바꿀지에 관한 것이다. 메시지의 발송 자체와 다른 정책의 효과는 별도 대비에 의존한다. 주지표와 보호 결과를 연결하고 적용 범위, 현재 선택, 실제 승인을 구분한다. 추가 확인에는 어떤 사업과 보호 기준, 용량 조건이 들어오면 보류를 다시 판단할지 적고, 현재 선택에 필요하지 않은 분석은 이유를 남겨 생략한다. B를 바로 채택하지 않는다고 현행 A가 모든 대안 중 최적이라는 뜻은 아니다. 추가 분석을 멈추더라도 실험 종료 규칙이나 필요한 보호 조치는 그대로 지킨다.','마지막 요약을 선택과 확인 종료의 기준으로 연결')
# Remove a repeated definition in chapter1 without touching the method contract.
edit(1,'TRI-V는 질문과 확인 절차,','TRI-V는 질문과 확인 절차, 적용 범위와 결정 기록을 연결하는 저자의 방법론이다. 공통 운용 기준은 그 사용설명서다. 검정은 기존 통계 방법을 따르며, 나의 제안은 각 방법을 어느 판단에 쓰고 근거가 부족하면 어디로 돌아갈지 연결하는 데 있다. 아직 다루지 못한 상황은 실제 적용 기록을 근거로 수정한다.','서로 반복하던 신규 검정법 면책과 기여 설명 통합')
for ch in [1,5,6,12]:
 def section(src):
  st=src.index(f'# {ch}장 ');en=src.find('\n# ',st+1);return src[st:len(src) if en<0 else en]
 a,b=section(base),section(text)
 assert re.findall(pattern,a)==re.findall(pattern,b),(ch,'numeric sequence')
 ep=r'[A-Za-z]+(?:[-/][A-Za-z]+)*';assert set(re.findall(ep,a))==set(re.findall(ep,b)),(ch,'English terms',set(re.findall(ep,a))^set(re.findall(ep,b)))
 assert re.findall(r'^\|.*$',a,re.M)==re.findall(r'^\|.*$',b,re.M),(ch,'table rows')
 assert re.findall(r'```.*?```',a,re.S)==re.findall(r'```.*?```',b,re.S),(ch,'code blocks')
 (OUT/f'ch{ch:02d}.md').write_text(b.strip()+'\n',encoding='utf-8',newline='\n')
assert not any(c in text for c in '\u00b7\u2022\u2027\u318d\u22c5\u30fb')
(OUT/'EDIT_CHANGES.json').write_text(json.dumps({'baseline':'e-book/exports/v11/ebook_review_v11.md','baseline_sha256':hashlib.sha256((ROOT/'e-book/exports/v11/ebook_review_v11.md').read_bytes()).hexdigest(),'changes':changes,'ordered_numbers_preserved':True,'english_term_sets_preserved':True,'tables_and_code_preserved':True,'human_approved':False},ensure_ascii=False,indent=2),encoding='utf-8',newline='\n')
print(json.dumps({'edited_paragraphs':len(changes),'chapters':sorted({x['chapter'] for x in changes}),'numeric_and_technical_preservation':'passed','source_characters_before':len(base),'source_characters_after':len(text)},ensure_ascii=False))
